const DecorationThemePanel=defineConsoleAsyncComponent(()=>import('../../components/console/DecorationThemePanel.vue'),'主题面板')
const DecorationNavigationPanel=defineConsoleAsyncComponent(()=>import('../../components/console/DecorationNavigationPanel.vue'),'底部导航')
