type View={assets?:DecorationApplicationAssets;components?:DecorationApplicationComponent[];defaults?:DecorationScheme|null;applicationKey:string|null;applications:{key:string;name:string}[];canWrite:boolean;version:number;current?:SchemeRow|null;currentSaved?:boolean;schemes:SchemeRow[];templates:SchemeRow[];systemTemplates?:SchemeRow[];targets:DecorationRoute[];groups?:{id:string;name:string}[];activeId:string|null;publishedAt:string|null;published:DecorationScheme|null}
const route=useRoute(),leftTab=ref<'components'|'structure'>('components'),dragId=ref('')
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/decoration',toast=useToast()
const initial=await useAsyncData('decoration:'+auth.session.value?.id+':'+tenantId,(_,{signal})=>auth.api<View>(endpoint+(typeof route.query.application==='string'?'?applicationKey='+encodeURIComponent(route.query.application):''),'GET',undefined,{signal}))
const data=ref<View|null>(initial.data.value||null),error=ref(initial.error.value?.message||''),busy=ref(''),selectedId=ref(''),form=ref<SchemeRow|null>(null),baseline=ref(''),page=ref<'home'|'profile'>(route.query.page==='profile'?'profile':'home'),tab=useRouteTab<'page'|'navigation'|'theme'>('page',['page','navigation','theme']),blockId=ref(''),picker=ref(false),pickerTarget=ref<{blockId?:string;itemId?:string;navigation?:boolean;background?:boolean;notice?:boolean}|null>(null)
const applyOpen=ref(false),applyTarget=ref<SchemeRow|null>(null),applySearch=ref(''),applyGroup=ref('all'),previewOpen=ref(false),previewing=ref(false),previewError=ref(''),previewLink=ref<{url:string;qr:string;expiresAt:string;localOnly:boolean}|null>(null)
let previewAttempt=0,previewController:AbortController|undefined
const componentSearch=ref(''),propertyTab=ref<'content'|'style'>('content'),previewMode=ref(false),canvasWidth=ref(390),templateOpen=ref(false),templateName=ref(''),templateId=ref(''),templateError=ref(''),history=ref<string[]>([]),historyIndex=ref(0)
let historyTimer:ReturnType<typeof setTimeout>|undefined
const availableBlocks=computed(()=>[...decorationBlocks,...(data.value?.components||[]).filter(c=>c.defaultBlock.type===c.type)]);
function createBlock(type:string){const custom=data.value?.components?.find(c=>c.type===type);return custom?{...clone(custom.defaultBlock),id:crypto.randomUUID()}:decorationBlock(type,crypto.randomUUID(),routes.value)}
const routes=computed(()=>data.value?.targets||decorationTargets)
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v)),dirty=computed(()=>!!form.value&&JSON.stringify(form.value)!==baseline.value),locked=computed(()=>!!busy.value||!data.value?.canWrite),discard=useDiscardChanges(()=>!!busy.value)
const currentBlock=computed(()=>form.value?.scheme[page.value].blocks.find(b=>b.id===blockId.value)),catalog=computed(()=>availableBlocks.value.filter(b=>b.type!=='image'&&b.pages.includes(page.value)&&b.label.includes(componentSearch.value.trim())))
const schemeSnapshot=computed(()=>form.value?JSON.stringify(form.value.scheme):'')
const publishedSnapshot=computed(()=>JSON.stringify(data.value?.published?normalizeDecorationScheme(data.value.published):null))
const draftChanged=computed(()=>!!form.value&&schemeSnapshot.value!==publishedSnapshot.value)
let disposed=false;const lifetime=new AbortController()
function fill(row:SchemeRow|null){form.value=row?clone(row):null;if(form.value)form.value.scheme=normalizeDecorationScheme(form.value.scheme);selectedId.value=row?.id||'';baseline.value=JSON.stringify(form.value);blockId.value='';discard.keep();resetHistory()}
fill(data.value?.current||data.value?.schemes[0]||null)
if(data.value&&!form.value)error.value='当前装修不可用，请返回页面装修选择应用'
blockId.value=''
const componentGroups=computed(()=>[{label:'应用组件',types:(data.value?.components||[]).filter(c=>c.defaultBlock.type===c.type).map(c=>c.type)},{label:'基础组件',types:['intro','features','text','banner','wechat-ad','links','collection','gallery','hot-area','notice','rich-text','activity','search-box','search','float','button','spacer','divider','showcase']},{label:'个人中心组件',types:['profile','membership','assets','orders']}])
const groupCatalog=(types:string[])=>types.flatMap(type=>catalog.value.filter(c=>c.type===type))
const blockIcons:Record<string,string>={collection:'i-lucide-panels-left-bottom','wechat-ad':'i-lucide-megaphone',intro:'i-lucide-panels-top-left',features:'i-lucide-layout-grid',assets:'i-lucide-wallet',orders:'i-lucide-receipt-text',profile:'i-lucide-user-round','hot-area':'i-lucide-scan','membership':'i-lucide-badge-check','member-level':'i-lucide-award','member-overview':'i-lucide-contact','rich-text':'i-lucide-text-cursor-input',activity:'i-lucide-layout-dashboard','search-box':'i-lucide-search',search:'i-lucide-search',float:'i-lucide-circle-dot',showcase:'i-lucide-panels-top-left',text:'i-lucide-file-text',image:'i-lucide-images',banner:'i-lucide-gallery-horizontal',links:'i-lucide-layout-grid',spacer:'i-lucide-move-vertical',divider:'i-lucide-minus',notice:'i-lucide-megaphone',gallery:'i-lucide-layout-dashboard',button:'i-lucide-square-mouse-pointer'}

const canvasHost=shallowRef<HTMLElement|null>(null),dragging=ref(false),dragPayload=shallowRef<DecorationDrag|null>(null),pointer=reactive({x:0,y:0}),dropIndex=ref<number|null>(null),dropLine=ref<{x:number;y:number;width:number}|null>(null),toolPosition=ref<{x:number;y:number}|null>(null)
let dragCandidate:{id:number;x:number;y:number;source:HTMLElement|null}|null=null,suppressClick=false,scrollFrame=0,toolsFrame=0,canvasObserver:ResizeObserver|undefined
const dragLabel=computed(()=>{const payload=dragPayload.value;return payload&&'type' in payload?availableBlocks.value.find(b=>b.type===payload.type)?.label:'移动组件'})
function startPointerDrag(event:PointerEvent,payload:DecorationDrag){
 if(locked.value||event.button!==0||'type' in payload&&!catalog.value.some(c=>c.type===payload.type))return
 const source=event.currentTarget instanceof HTMLElement?event.currentTarget:null
 source?.setPointerCapture(event.pointerId);dragCandidate={id:event.pointerId,x:event.clientX,y:event.clientY,source};dragPayload.value=payload
 window.addEventListener('pointermove',movePointerDrag,{passive:false});window.addEventListener('pointerup',endPointerDrag);window.addEventListener('pointercancel',cancelPointerDrag);window.addEventListener('blur',cancelPointerDrag);window.addEventListener('keydown',cancelDragKey)
}
function updateDrop(){
 const content=canvasHost.value?.querySelector<HTMLElement>('.preview-content'),box=content?.getBoundingClientRect();dropIndex.value=null;dropLine.value=null
 if(!content||!box||pointer.x<box.left||pointer.x>box.right||pointer.y<box.top||pointer.y>box.bottom)return
 if(pointer.y<box.top+28)content.scrollTop-=8;else if(pointer.y>box.bottom-28)content.scrollTop+=8
 const cards=[...content.querySelectorAll<HTMLElement>('[data-block-id]')],before=cards.find(card=>{const r=card.getBoundingClientRect();return pointer.y<r.top+r.height/2}),blocks=form.value!.scheme[page.value].blocks
 dropIndex.value=before?blocks.findIndex(b=>b.id===before.dataset.blockId):blocks.length
 const y=before?.getBoundingClientRect().top??cards.at(-1)?.getBoundingClientRect().bottom??box.top
 dropLine.value={x:box.left+4,y:Math.max(box.top+2,Math.min(box.bottom-2,y)),width:box.width-8}
}
function dragTick(){if(!dragging.value)return;updateDrop();scrollFrame=requestAnimationFrame(dragTick)}
function movePointerDrag(event:PointerEvent){if(!dragCandidate||event.pointerId!==dragCandidate.id)return;if(!dragging.value&&Math.hypot(event.clientX-dragCandidate.x,event.clientY-dragCandidate.y)<5)return;event.preventDefault();pointer.x=event.clientX;pointer.y=event.clientY;suppressClick=true;if(!dragging.value){dragging.value=true;scrollFrame=requestAnimationFrame(dragTick)}}
function checkAdd(type:string){
 const blocks=form.value?.scheme[page.value].blocks;if(!blocks)return false
 if(canAddDecoration(blocks,type))return true
 const existing=singleDecorationTypes.includes(type)?blocks.find(b=>b.type===type):undefined
 if(existing){blockId.value=existing.id;propertyTab.value='content';void nextTick(()=>canvasHost.value?.querySelector<HTMLElement>('[data-block-id="'+existing.id+'"]')?.scrollIntoView({block:'nearest',inline:'nearest'}))}
 toast.add({id:'decoration-add-limit',title:existing?(availableBlocks.value.find(b=>b.type===type)?.label||'该组件')+'只能添加一个':'每个页面最多添加 30 个组件',description:existing?'已定位到页面中的现有组件':undefined,color:'info',icon:'i-lucide-info'})
 return false
}
function insertAt(payload:DecorationDrag,at:number){if(locked.value||!form.value||'type' in payload&&!checkAdd(payload.type))return;checkpoint();const result=placeDecorationBlock(form.value.scheme[page.value].blocks,payload,at,type=>createBlock(type));if(!result)return;form.value.scheme[page.value].blocks=result.blocks;blockId.value=result.id;propertyTab.value='content';checkpoint()}
function cancelDragKey(event:KeyboardEvent){if(event.key==='Escape')cancelPointerDrag()}
function cancelPointerDrag(){if(typeof window==='undefined')return;if(dragCandidate?.source?.hasPointerCapture(dragCandidate.id))dragCandidate.source.releasePointerCapture(dragCandidate.id);window.removeEventListener('pointermove',movePointerDrag);window.removeEventListener('pointerup',endPointerDrag);window.removeEventListener('pointercancel',cancelPointerDrag);window.removeEventListener('blur',cancelPointerDrag);window.removeEventListener('keydown',cancelDragKey);cancelAnimationFrame(scrollFrame);dragCandidate=null;dragPayload.value=null;dragging.value=false;dropIndex.value=null;dropLine.value=null;setTimeout(()=>{suppressClick=false},0)}
function endPointerDrag(event:PointerEvent){if(!dragCandidate||event.pointerId!==dragCandidate.id)return;if(dragging.value){pointer.x=event.clientX;pointer.y=event.clientY;updateDrop();if(dragPayload.value&&dropIndex.value!==null)insertAt(dragPayload.value,dropIndex.value)}cancelPointerDrag()}
function selectBlock(id:string){if(suppressClick)return;blockId.value=id;propertyTab.value='content'}
function warnBeforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue=''}}
function updateTools(){const host=canvasHost.value;if(!host||!blockId.value||tab.value!=='page'){toolPosition.value=null;return}const block=[...host.querySelectorAll<HTMLElement>('[data-block-id]')].find(el=>el.dataset.blockId===blockId.value),content=host.querySelector('.preview-content'),screen=host.querySelector('.phone-preview-size');if(!block||!content||!screen)return;const r=block.getBoundingClientRect(),c=content.getBoundingClientRect(),phone=screen.getBoundingClientRect();toolPosition.value=r.bottom<c.top||r.top>c.bottom?null:{x:phone.right+8,y:Math.max(c.top,Math.min(r.top,c.bottom-140))}}
function scheduleTools(){if(!toolsFrame)toolsFrame=requestAnimationFrame(()=>{toolsFrame=0;updateTools()})}
watch(()=>[blockId.value,page.value,tab.value,canvasWidth.value,schemeSnapshot.value],scheduleTools,{flush:'post'})
onMounted(()=>{canvasObserver=new ResizeObserver(scheduleTools);if(canvasHost.value)canvasObserver.observe(canvasHost.value);window.addEventListener('scroll',scheduleTools,true);window.addEventListener('beforeunload',warnBeforeUnload)})
onBeforeUnmount(()=>{cancelPointerDrag();canvasObserver?.disconnect();if(typeof window!=='undefined'){cancelAnimationFrame(toolsFrame);window.removeEventListener('scroll',scheduleTools,true);window.removeEventListener('beforeunload',warnBeforeUnload)}})

watch(()=>route.query.page,value=>{page.value=value==='profile'?'profile':'home'})
function selectPage(value:'home'|'profile'|'navigation'|'theme'){if(value==='home'||value==='profile')page.value=value;void navigateTo({path:route.path,query:{...route.query,tab:value==='navigation'?'navigation':value==='theme'?'theme':undefined,page:value==='home'||value==='profile'?value:page.value}});blockId.value='';propertyTab.value='content'}
function copyBlock(id:string){if(locked.value||!form.value)return;const blocks=form.value.scheme[page.value].blocks,b=blocks.find(v=>v.id===id);if(!b||!checkAdd(b.type))return;const copy=clone(b);copy.id=crypto.randomUUID();blocks.splice(blocks.indexOf(b)+1,0,copy);blockId.value=copy.id}
function drop(id:string){if(dragId.value.startsWith('new:')){const type=dragId.value.slice(4);blockId.value=id;add(type);dragId.value='';return}if(locked.value||!form.value||!dragId.value||dragId.value===id)return;const blocks=form.value.scheme[page.value].blocks,from=blocks.findIndex(b=>b.id===dragId.value),to=blocks.findIndex(b=>b.id===id);if(from<0||to<0)return;const [b]=blocks.splice(from,1);blocks.splice(to,0,b!);dragId.value=''}
function guard(action:()=>void){if(busy.value)return;if(dirty.value){discard.request(()=>{discard.keep();action()});return}action()}
function cancel(){fill(data.value?.schemes.find(s=>s.id===selectedId.value)||null);error.value=''}
async function refresh(applicationKey=data.value?.applicationKey||''){
 guard(()=>void read(applicationKey))
}
async function read(applicationKey:string){busy.value='refresh';if(disposed)return;error.value='';try{const value=await auth.api<View>(endpoint+(applicationKey?'?applicationKey='+encodeURIComponent(applicationKey):''),'GET',undefined,{signal:lifetime.signal});if(disposed)return;data.value=value;fill(value.schemes.find(s=>s.id===selectedId.value)||null)}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=''}}
async function mutate(action:'save'|'template'){
 if(locked.value||!form.value||!data.value?.applicationKey)return;
 if(action==='template'&&!templateName.value.trim()){templateError.value='请填写模板名称';return}
 busy.value=action;error.value='';const row=clone(form.value),selected=blockId.value;checkpoint();
 try{const value=action==='save'?await persistDraft(row,'save'):await auth.api<View>(endpoint+'/'+encodeURIComponent(data.value.applicationKey),'PUT',{version:data.value.version,action:'save-template',id:templateId.value,name:templateName.value.trim(),scheme:row.scheme},{signal:lifetime.signal});if(disposed)return;data.value=value;if(action==='template'){templateOpen.value=false;toast.add({title:'已存为模板',color:'success'});return}acceptSaved(row,value);blockId.value=selected;discard.keep();const warnings=decorationWarnings(form.value!.scheme);toast.add({title:'已保存并生效',description:warnings.length?warnings.join('；'):undefined,color:warnings.length?'warning':'success',close:true,duration:6000})}catch(e:any){if(!disposed){if(action==='template')templateError.value=e.message||'模板保存失败';else error.value=e.message||'保存失败，当前修改已保留'}}finally{if(!disposed)busy.value=''}
}
function add(type:string){if(suppressClick)return;if(locked.value||!form.value)return;const blocks=form.value.scheme[page.value].blocks;if(!availableBlocks.value.some(b=>b.type===type&&b.pages.includes(page.value))||!checkAdd(type))return;checkpoint();const b=createBlock(type),index=blocks.findIndex(v=>v.id===blockId.value);blocks.splice(index>=0?index+1:blocks.length,0,b);blockId.value=b.id;propertyTab.value='content';checkpoint()}
function move(id:string,offset:number){if(locked.value||!form.value)return;const blocks=form.value.scheme[page.value].blocks,index=blocks.findIndex(b=>b.id===id);if(index<0||index+offset<0||index+offset>=blocks.length)return;const [value]=blocks.splice(index,1);blocks.splice(index+offset,0,value!)}
function removeBlock(){if(locked.value||!form.value)return;const blocks=form.value.scheme[page.value].blocks,index=blocks.findIndex(b=>b.id===blockId.value);if(index<0)return;blocks.splice(index,1);blockId.value=blocks[Math.max(0,index-1)]?.id||''}
function addItem(navigation=false){if(locked.value||!form.value)return;const items=navigation?form.value.scheme.navigation.items:currentBlock.value?.items;if(!items||items.length>=(navigation?5:10))return;items.push({id:crypto.randomUUID(),label:'新入口',target:navigation?'profile':'',imageId:null})}
function pickBlockAsset(target:{itemId?:string;notice?:boolean}){if(currentBlock.value)pick({blockId:currentBlock.value.id,...target})}
function pick(target:{blockId?:string;itemId?:string;navigation?:boolean;background?:boolean;notice?:boolean}){if(locked.value)return;pickerTarget.value=target;picker.value=true}
function selectedImage(image:{id:string}){if(!form.value||!pickerTarget.value)return;const t=pickerTarget.value;if(t.navigation){const item=form.value.scheme.navigation.items.find(i=>i.id===t.itemId);if(item)item.imageId=image.id}else{const block=form.value.scheme[page.value].blocks.find(b=>b.id===t.blockId);if(!block)return;if(t.background){block.appearance={...decorationAppearance(block),backgroundImageId:image.id}}else if(t.notice){block.options={...decorationOptions(block),noticeImageId:image.id,noticePreset:'custom'}}else if(t.itemId){const item=block.items.find(i=>i.id===t.itemId);if(item){item.imageId=image.id;const picture=new Image();picture.onload=()=>{const current=form.value?.scheme[page.value].blocks.find(b=>b.id===t.blockId)?.items.find(i=>i.id===t.itemId);if(current?.imageId===image.id){current.imageWidth=picture.naturalWidth;current.imageHeight=picture.naturalHeight}};picture.src=imageUrl(image.id)}}else block.imageId=image.id}}
function imageUrl(id:string){if(data.value?.assets?.[id])return data.value.assets[id]!.web;return '/api/v1/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data.value?.applicationKey||'')+'/'+encodeURIComponent(id)+'/content?purpose=library'}
function reorderItem(items:DecorationItem[],i:number,offset:number){if(locked.value||i+offset<0||i+offset>=items.length)return;const [value]=items.splice(i,1);items.splice(i+offset,0,value!)}
watch(page,()=>{blockId.value=''})
function leaveEditor(to:{fullPath:string}){if(busy.value)return false;if(dirty.value){discard.request(()=>{cancel();void navigateTo(to.fullPath)});return false}}
onBeforeRouteLeave(leaveEditor)
onBeforeRouteUpdate((to,from)=>{
 const documentKey=(query:typeof to.query)=>JSON.stringify([query.application,query.scheme,query.template])
 if(documentKey(to.query)!==documentKey(from.query))return leaveEditor(to)
})
onBeforeUnmount(()=>{disposed=true;previewAttempt++;previewController?.abort();lifetime.abort();busy.value='';clearTimeout(historyTimer)})

function resetHistory(){clearTimeout(historyTimer);history.value=form.value?[schemeSnapshot.value]:[];historyIndex.value=0}
function checkpoint(){clearTimeout(historyTimer);if(!form.value)return;const value=schemeSnapshot.value;if(value===history.value[historyIndex.value])return;history.value=history.value.slice(0,historyIndex.value+1);history.value.push(value);if(history.value.length>50)history.value.shift();historyIndex.value=history.value.length-1}
function undo(){if(locked.value||!form.value)return;checkpoint();if(historyIndex.value<=0)return;form.value.scheme=JSON.parse(history.value[--historyIndex.value]!);blockId.value=''}
function redo(){if(locked.value||!form.value||historyIndex.value>=history.value.length-1)return;form.value.scheme=JSON.parse(history.value[++historyIndex.value]!);blockId.value=''}
function saveTemplate(){if(locked.value)return;templateName.value=form.value?.name||'';templateId.value=crypto.randomUUID();templateError.value='';templateOpen.value=true}
function canvasNavigate(target:DecorationLink){if(target==='home'||target==='profile')selectPage(target);else if(target)toast.add({title:'跳转至 '+(routes.value.find(r=>r.key===target)?.label||'页面'),description:'此入口在小程序中打开。',color:'neutral'})}
function updateLayout(value:string){if(!currentBlock.value||locked.value)return;currentBlock.value.appearance={...decorationAppearance(currentBlock.value),layout:value as 'grid'|'list'|'left-large'|'top-large'}}
function updateStyle(key:'padding'|'gap'|'radius'|'fontSize'|'columns',value:number){if(!currentBlock.value||locked.value)return;currentBlock.value.appearance={...decorationAppearance(currentBlock.value),[key]:value}}
watch(schemeSnapshot,()=>{clearTimeout(historyTimer);historyTimer=setTimeout(checkpoint,300)})

function persistDraft(row:SchemeRow,action:'save'|'save-and-activate'){const key=data.value!.applicationKey!;return saveDecorationDraft({base:JSON.parse(baseline.value) as SchemeRow,local:row,version:data.value!.version,action,read:()=>auth.api<View>(endpoint+'?applicationKey='+encodeURIComponent(key),'GET',undefined,{signal:lifetime.signal}),write:body=>auth.api<View>(endpoint+'/'+encodeURIComponent(key),'PUT',body,{signal:lifetime.signal})})}
function acceptSaved(row:SchemeRow,result:View){if(disposed||form.value?.id!==row.id)return;const saved=result.schemes.find(s=>s.id===row.id);if(!saved)return;const normalized={...saved,scheme:normalizeDecorationScheme(saved.scheme)};form.value=mergeDecorationDraft(row,form.value,normalized);data.value=result;baseline.value=JSON.stringify(normalized)}


const builtinTemplate=computed(()=>({id:'framework-default',name:'框架默认方案',scheme:data.value?.defaults||defaultDecoration(),updatedAt:'',groupId:null,coverId:null}))
const requestedTemplate=typeof route.query.template==='string'?[...(data.value?.systemTemplates||[builtinTemplate.value]),...(data.value?.templates||[])].find(t=>t.id===route.query.template):null
if(requestedTemplate&&form.value){form.value.scheme=normalizeDecorationScheme(requestedTemplate.scheme);checkpoint()}
else if(route.query.template)error.value='模板不存在或已删除，已保留当前装修内容'
function openApply(){if(locked.value)return;applySearch.value='';applyGroup.value='all';applyTarget.value=null;applyOpen.value=true}
function applyTemplate(){if(locked.value||!form.value||!applyTarget.value)return;checkpoint();form.value.scheme=normalizeDecorationScheme(applyTarget.value.scheme);checkpoint();blockId.value='';selectPage('home');applyOpen.value=false;applyTarget.value=null;toast.add({title:'模板已套用到当前装修，可撤销',color:'success'})}
async function openPreview(){if(previewMode.value){previewMode.value=false;return}if(!form.value||!data.value?.applicationKey||previewing.value)return;previewOpen.value=true;previewing.value=true;previewError.value='';previewLink.value=null;const n=++previewAttempt;previewController?.abort();previewController=new AbortController();try{const result=await auth.api<{url:string;qr:string;expiresAt:string;localOnly:boolean}>(endpoint+'/'+encodeURIComponent(data.value.applicationKey)+'/preview','POST',{name:form.value.name,page:page.value,scheme:clone(form.value.scheme)},{signal:previewController.signal});if(!disposed&&n===previewAttempt)previewLink.value=result}catch(e:any){if(!disposed&&n===previewAttempt)previewError.value=e.message||'预览生成失败'}finally{if(!disposed&&n===previewAttempt)previewing.value=false}}
watch(previewOpen,value=>{if(!value){previewAttempt++;previewController?.abort();previewing.value=false}})
</script>
<template><div class="decoration-studio" :class="{'is-preview':previewMode}">
 <div v-if="dragging" class="studio-drag-ghost" :style="{left:pointer.x+14+'px',top:pointer.y+14+'px'}">{{dragLabel}}</div><div v-if="dragging&&dropLine" class="studio-drop-line" :style="{left:dropLine.x+'px',top:dropLine.y+'px',width:dropLine.width+'px'}"/><template v-if="form&&data"><header class="studio-header"><div class="studio-identity"><UButton to="/admin/decoration" icon="i-lucide-arrow-left" color="neutral" variant="ghost" aria-label="返回页面装修">退出编辑</UButton><span class="studio-divider"/><div><strong>{{form.name}}</strong><span class="studio-state" :class="{dirty}"><i/>{{dirty?'未保存修改':data.currentSaved===false?'默认内容，尚未保存':draftChanged?'待保存生效':'已保存并生效'}}</span></div></div><nav class="studio-page-tabs" aria-label="编辑区域"><button v-for="entry in [{key:'home',label:'首页',icon:'i-lucide-house'},{key:'profile',label:'个人中心',icon:'i-lucide-user-round'},{key:'theme',label:'主题',icon:'i-lucide-palette'},{key:'navigation',label:'底部导航',icon:'i-lucide-panel-bottom'}]" :key="entry.key" type="button" :class="{active:tab==='page'?page===entry.key:tab===entry.key}" @click="selectPage(entry.key as 'home'|'profile'|'theme'|'navigation')"><UIcon :name="entry.icon"/>{{entry.label}}</button></nav><div class="studio-header-actions"><div class="studio-history"><UButton color="neutral" variant="ghost" icon="i-lucide-undo-2" aria-label="撤销" :disabled="locked||historyIndex<=0&&!dirty" @click="undo"/><UButton color="neutral" variant="ghost" icon="i-lucide-redo-2" aria-label="重做" :disabled="locked||historyIndex>=history.length-1" @click="redo"/></div><UButton color="neutral" :variant="previewMode?'soft':'ghost'" icon="i-lucide-eye" :loading="previewing" @click="openPreview">{{previewMode?'返回编辑':'预览'}}</UButton><UButton color="neutral" variant="outline" icon="i-lucide-layout-template" :disabled="locked" @click="openApply">套用模板</UButton><UButton color="neutral" variant="outline" icon="i-lucide-bookmark" :disabled="locked" :loading="busy==='template'" @click="saveTemplate">存为模板</UButton><UButton color="neutral" variant="outline" :disabled="locked||(!dirty&&!draftChanged&&data.currentSaved!==false)" :loading="busy==='save'" @click="mutate('save')">保存</UButton></div></header>
 <div v-if="error" class="studio-error" role="alert"><UIcon name="i-lucide-circle-alert"/><div class="min-w-0 flex-1"><strong>当前修改尚未保存</strong><p>{{error}}</p><div class="flex gap-3 mt-2"><UButton size="xs" color="neutral" variant="outline" :disabled="locked" @click="mutate('save')">重试保存</UButton><UButton size="xs" color="neutral" variant="ghost" :disabled="locked" @click="refresh()">重新读取</UButton></div></div><UButton size="xs" color="neutral" variant="ghost" icon="i-lucide-x" aria-label="关闭保存提示" @click="error=''"/></div>
 <div class="studio-main"><aside v-if="!previewMode" class="studio-library">
  <template v-if="tab==='page'"><div class="studio-panel-tabs"><button type="button" :class="{active:leftTab==='components'}" @click="leftTab='components'">添加组件</button><button type="button" :class="{active:leftTab==='structure'}" @click="leftTab='structure'">页面结构<span>{{form.scheme[page].blocks.length}}</span></button></div><div v-if="leftTab==='components'" class="studio-components"><label class="studio-search"><UIcon name="i-lucide-search"/><input v-model="componentSearch" placeholder="搜索组件" aria-label="搜索组件"/></label><section v-for="group in componentGroups.filter(g=>catalog.some(c=>g.types.includes(c.type)))" :key="group.label"><h3>{{group.label}}</h3><div class="studio-component-grid"><button v-for="item in groupCatalog(group.types)" :key="item.type" type="button" :disabled="locked" :draggable="false" @pointerdown="startPointerDrag($event,{type:item.type})" @click="add(item.type)"><span><DecorationComponentIcon :type="item.type" :fallback="blockIcons[item.type]"/></span><b>{{item.label}}</b></button></div></section><p v-if="!catalog.length" class="studio-help">没有匹配的组件</p></div>
  <div v-else class="studio-structure"><div v-for="(block,index) in form.scheme[page].blocks" :key="block.id" class="studio-layer" :class="{active:block.id===blockId,hidden:!block.enabled}" :draggable="false" @dragover.prevent @drop.prevent="drop(block.id);checkpoint()"><button type="button" class="studio-layer-select" @pointerdown="startPointerDrag($event,{id:block.id})" @click="selectBlock(block.id)"><UIcon name="i-lucide-grip-vertical"/><UIcon :name="blockIcons[block.type]||'i-lucide-layout-grid'"/><span>{{block.title||availableBlocks.find(b=>b.type===block.type)?.label}}</span><small>{{String(index+1).padStart(2,'0')}}</small></button><div v-if="block.id===blockId" class="studio-layer-actions"><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-up" aria-label="上移组件" :disabled="locked||index===0" @click="checkpoint();move(block.id,-1);checkpoint()"/><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-down" aria-label="下移组件" :disabled="locked||index===form.scheme[page].blocks.length-1" @click="checkpoint();move(block.id,1);checkpoint()"/><UButton color="neutral" variant="ghost" size="xs" :icon="block.enabled?'i-lucide-eye':'i-lucide-eye-off'" aria-label="切换组件显示" :disabled="locked" @click="checkpoint();block.enabled=!block.enabled;checkpoint()"/><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-copy" aria-label="复制组件" :disabled="locked" @click="checkpoint();copyBlock(block.id);checkpoint()"/></div></div></div>
  </template>
  <div v-else class="studio-section-guide"><UIcon :name="tab==='theme'?'i-lucide-palette':'i-lucide-panel-bottom'"/><h2>{{tab==='theme'?'统一整体风格':'把常用入口放在底部'}}</h2><p>{{tab==='theme'?'在右侧选择配色与布局预设，页面和组件可以跟随主题，也可以单独设置。':'导航名称、图标、排序与跳转页面在右侧配置，与当前方案一起保存。'}}</p><div class="studio-scope-note"><UIcon name="i-lucide-layers"/>仅编辑当前方案</div></div></aside>
  <main class="studio-canvas"><div class="studio-canvas-bar"><div><UIcon :name="page==='home'?'i-lucide-house':'i-lucide-user-round'"/><span>{{form.scheme[page].title}}</span><small>{{previewMode?'预览效果':'实时画布'}}</small></div><div><button v-if="previewMode||tab!=='page'" type="button" @click="page=page==='home'?'profile':'home'">切换{{page==='home'?'个人中心':'首页'}}</button><USelect v-model="canvasWidth" :items="[{label:'390 × 844',value:390},{label:'430 × 932',value:430}]" aria-label="预览尺寸" icon="i-lucide-smartphone" color="neutral" variant="ghost" size="sm" class="studio-viewport-select" :content="{align:'end',sideOffset:8}" :ui="{content:'min-w-40',item:'py-2.5 text-sm'}"/><UButton v-if="!previewMode&&tab==='page'" icon="i-lucide-settings" color="neutral" variant="ghost" size="xs" @click="blockId=''">页面设置</UButton></div></div>
   <div ref="canvasHost" class="studio-canvas-scroll" @click.self="blockId=''" @dragover.prevent @drop.prevent="dragId.startsWith('new:')&&(add(dragId.slice(4)),dragId='')"><div class="studio-phone-wrap" :style="{width:canvasWidth+'px'}"><div v-if="!previewMode&&currentBlock&&tab==='page'&&toolPosition&&!dragging" class="studio-floating-tools" :style="{left:toolPosition.x+'px',top:toolPosition.y+'px'}" aria-label="当前组件操作"><UButton icon="i-lucide-chevron-up" color="neutral" variant="ghost" size="xs" aria-label="画布上移组件" :disabled="locked||form.scheme[page].blocks[0]?.id===blockId" @click="checkpoint();move(blockId,-1);checkpoint()"/><UButton icon="i-lucide-chevron-down" color="neutral" variant="ghost" size="xs" aria-label="画布下移组件" :disabled="locked||form.scheme[page].blocks.at(-1)?.id===blockId" @click="checkpoint();move(blockId,1);checkpoint()"/><UButton icon="i-lucide-copy" color="neutral" variant="ghost" size="xs" aria-label="画布复制组件" :disabled="locked" @click="checkpoint();copyBlock(blockId);checkpoint()"/><UButton icon="i-lucide-trash-2" color="error" variant="ghost" size="xs" aria-label="画布删除组件" :disabled="locked" @click="checkpoint();removeBlock();checkpoint()"/></div><div class="studio-phone-slot"><PhonePreviewFrame :mini-program="page==='home'&&form.scheme[page].showHeader===true" :width="canvasWidth" :height="canvasWidth===430?932:844" :bottom-color="form.scheme.navigation.enabled?decorationNavigation(form.scheme).background:decorationPageBackground(form.scheme,page)"><DecorationPreview :assets="data?.assets" :components="data?.components" :mini-program="page==='home'&&form.scheme[page].showHeader===true" :scheme="form.scheme" :page="page" :selected="!previewMode&&tab==='page'?blockId:''" :image-url="imageUrl" :editable="!previewMode&&tab==='page'" @select="selectBlock" @select-page="blockId=''" @drag="(id:string,event:PointerEvent)=>startPointerDrag(event,{id})" @drop-block="checkpoint();drop($event);checkpoint()" @navigate="canvasNavigate"/></PhonePreviewFrame></div><p class="studio-canvas-caption"><UIcon name="i-lucide-smartphone"/>{{canvasWidth}} px · {{previewMode?'当前草稿预览':'修改实时显示，保存后生效'}}</p></div></div>
  </main>
  <aside v-if="!previewMode" class="studio-properties"><template v-if="tab==='theme'"><div class="studio-properties-heading"><span class="studio-property-icon"><UIcon name="i-lucide-palette"/></span><div><h2>主题风格</h2><small>当前方案的全局样式</small></div></div><div class="studio-properties-body"><DecorationThemePanel v-if="form.scheme.theme" v-model="form.scheme.theme" :disabled="locked" @update:model-value="checkpoint" @inherit-all="checkpoint();inheritDecorationTheme(form.scheme);checkpoint()"/></div></template>
   <template v-else-if="tab==='navigation'"><div class="studio-properties-heading"><span class="studio-property-icon"><UIcon name="i-lucide-panel-bottom"/></span><div><h2>底部导航</h2><small>常用入口与选中样式</small></div></div><div class="studio-properties-body"><DecorationNavigationPanel v-model="form.scheme.navigation" :targets="routes" :disabled="locked" :image-url="imageUrl" @pick="pick({navigation:true,itemId:$event})"/></div></template>
   <template v-else-if="!currentBlock"><div class="studio-properties-heading"><span class="studio-property-icon"><UIcon name="i-lucide-file-text"/></span><div><h2>页面设置</h2><small>{{page==='home'?'首页':'个人中心'}}</small></div></div><div class="studio-properties-body space-y-6"><label class="studio-field"><span>页面标题</span><ConsoleInput v-model="form.scheme[page].title" :maxlength="30" :disabled="locked"/></label><DecorationHeaderPanel v-if="page==='home'" :key="page" v-model="form.scheme[page]" :disabled="locked" :image-url="imageUrl" :material-endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data?.applicationKey||'')" :routes="routes"/><label class="studio-switch"><span>背景跟随主题</span><USwitch v-model="form.scheme[page].inheritTheme" :disabled="locked" aria-label="页面背景跟随主题"/></label><DecorationColorField v-if="!form.scheme[page].inheritTheme" v-model="form.scheme[page].background" label="页面背景" :disabled="locked"/><button type="button" class="studio-theme-link" @click="selectPage('theme')"><UIcon name="i-lucide-palette"/><span>调整主题风格<small>统一颜色、字号、圆角与间距</small></span><UIcon name="i-lucide-chevron-right"/></button></div></template>
   <template v-else><div class="studio-properties-heading"><span class="studio-property-icon"><UIcon :name="blockIcons[currentBlock.type]||'i-lucide-layout-grid'"/></span><div><h2>{{availableBlocks.find(b=>b.type===currentBlock?.type)?.label}}</h2><small>组件设置</small></div><USwitch v-model="currentBlock.enabled" :disabled="locked" aria-label="显示组件" class="ml-auto"/></div><div class="studio-panel-tabs"><button type="button" :class="{active:propertyTab==='content'}" @click="propertyTab='content'">内容</button><button type="button" :class="{active:propertyTab==='style'}" @click="propertyTab='style'">样式</button></div>
    <div class="studio-properties-body"><DecorationBlockStylePanel v-if="propertyTab==='style'" :model-value="currentBlock" :theme="form.scheme.theme" :disabled="locked" :image-url="imageUrl" @update:model-value="Object.assign(currentBlock!,$event)" @pick-background="pick({blockId:currentBlock.id,background:true})"/><DecorationBlockContentPanel :previous-block="form.scheme[page].blocks[form.scheme[page].blocks.findIndex(b=>b.id===currentBlock?.id)-1]" :collection-sources="data?.components?.filter(c=>c.renderer==='collection')" :application-component="data?.components?.find(c=>c.type===currentBlock?.type)" v-else :first="form.scheme[page].blocks.find(b=>b.enabled)?.id===currentBlock.id" :model-value="currentBlock" :disabled="locked" :routes="routes" :image-url="imageUrl" :material-endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data?.applicationKey||'')" @update:model-value="Object.assign(currentBlock!,$event)" @checkpoint="checkpoint" @pick="pickBlockAsset"/></div></template>
  </aside></div><footer class="studio-status-footer"><span><UIcon name="i-lucide-shield-check"/>编辑仅在当前画布预览，保存后生效</span><span>{{form.scheme.home.blocks.length+form.scheme.profile.blocks.length}} 个组件<span class="studio-footer-dot">·</span>{{busy==='save'?'正在保存…':dirty?'未保存':'已保存'}}<button type="button" :disabled="!!busy" aria-label="重新读取方案" @click="refresh()"><UIcon name="i-lucide-refresh-cw" :class="{'animate-spin':busy==='refresh'}"/></button></span></footer></template>
 <div v-else class="studio-missing"><UAlert :title="error||'正在读取方案'" :color="error?'error':'neutral'"/><UButton to="/admin/decoration" color="neutral" variant="outline">返回页面装修</UButton></div>
 <MaterialPicker v-model:open="picker" portal="tenant" purpose="library" kind="image" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(data?.applicationKey||'')" @select="selectedImage"/>
