 <ConsoleDialog v-model:open="templateOpen" title="存为模板" description="保存当前编辑内容的独立副本，不替换正在使用的方案。" :dismissible="!busy" :close="!busy"><template #body><form id="save-decoration-template" class="space-y-4" @submit.prevent="mutate('template')"><UAlert v-if="templateError" color="error" :title="templateError"/><label class="studio-field"><span>模板名称</span><ConsoleInput v-model="templateName" :maxlength="40" required :disabled="!!busy" placeholder="例如：品牌通用模板"/></label><p class="text-xs text-muted leading-6">包含首页、个人中心、主题风格与底部导航。套用模板只改变当前编辑内容，保存后才保留。</p></form></template><template #footer><div class="flex justify-end gap-3 w-full"><UButton color="neutral" variant="outline" :disabled="!!busy" @click="templateOpen=false">取消</UButton><UButton form="save-decoration-template" type="submit" :disabled="locked" :loading="busy==='template'">保存模板</UButton></div></template></ConsoleDialog>

 <ConsoleDialog v-model:open="applyOpen" title="套用模板" size="picker"><template #body><div class="flex gap-3 mb-5"><div class="flex-1 min-w-0"><ConsoleInput v-model="applySearch" placeholder="搜索模板" aria-label="搜索可套用模板"/></div><USelect v-model="applyGroup" :items="[{label:'全部分类',value:'all'},{label:'未分类',value:'ungrouped'},...(data?.groups||[]).map(g=>({label:g.name,value:g.id}))]" class="w-40"/></div><div class="studio-template-grid"><button v-for="item in [...(data?.systemTemplates||[builtinTemplate]),...(data?.templates||[])].filter(t=>t.name.includes(applySearch.trim())&&(applyGroup==='all'||(applyGroup==='ungrouped'?!t.groupId:t.groupId===applyGroup)))" :key="item.id" type="button" :class="{active:applyTarget?.id===item.id}" @click="applyTarget=item"><div class="studio-template-cover"><img v-if="item.coverId" :src="imageUrl(item.coverId)" alt=""/><UIcon v-else name="i-lucide-layout-template"/></div><strong>{{item.name}}</strong><small>{{item.scheme.home.blocks.length+item.scheme.profile.blocks.length}} 个组件</small></button></div><UAlert v-if="applyTarget" color="warning" variant="subtle" class="mt-5" title="将替换当前方案的首页、个人中心、主题和导航" description="套用后可预览和撤销，点击保存才生效。"/></template><template #footer><div class="flex justify-end gap-3 w-full"><UButton color="neutral" variant="outline" @click="applyOpen=false">取消</UButton><UButton :disabled="!applyTarget||locked" @click="applyTemplate">确认套用</UButton></div></template></ConsoleDialog>
 <ConsoleDialog v-model:open="previewOpen" title="页面预览" description="预览点击时的当前草稿，不会保存或改变用户端页面。" size="form"><template #body><div v-if="previewing" class="py-16 text-center text-sm text-muted">正在生成预览…</div><UAlert v-else-if="previewError" color="error" :title="previewError"><template #actions><UButton @click="openPreview">重试</UButton></template></UAlert><div v-else-if="previewLink" class="studio-qr-preview"><img :src="previewLink.qr" alt="当前草稿预览二维码"/><p>{{previewLink.localOnly?'当前地址仅本机可访问':'用手机微信或浏览器扫码预览'}}</p><small>{{dateTime(previewLink.expiresAt)}} 失效</small><ConsoleAccessLink :url="previewLink.url" label="草稿预览地址"/><p v-if="previewLink.localOnly" class="text-xs text-muted leading-6">手机访问需要使用手机可访问的后台地址，本地回环地址不能在手机打开。</p></div></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" @click="previewOpen=false;previewMode=true">画布预览</UButton><UButton v-if="previewLink" :to="previewLink.url" external target="_blank" rel="noopener" icon="i-lucide-external-link">新窗口打开</UButton></div></template></ConsoleDialog>
</div></template>
